const $ = (q,el=document)=>el.querySelector(q);
const icons={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',music:'M9 18V5l12-2v13M9 8l12-2M9 18c0 1.7-1.6 3-3.5 3S2 20 2 18.5 3.6 16 5.5 16 9 16.5 9 18Zm12-2c0 1.7-1.6 3-3.5 3S14 18 14 16.5s1.6-2.5 3.5-2.5 3.5.5 3.5 2Z',book:'M12 5v16M3 3c4-1 7 0 9 2 2-2 5-3 9-2v16c-4-1-7 0-9 2-2-2-5-3-9-2Z',chart:'M4 20h17M7 16v-5m5 5V4m5 12V8',tune:'M5 3v18M19 3v18M12 3v18M2 8h6m1 7h6m1-9h6',settings:'M9 4V2h6v2l3 2 2-1 3 5-2 2v3l2 1-3 5-2-1-3 2v2H9v-2l-3-2-2 1-3-5 2-1v-3l-2-2 3-5 2 1Zm6 8a3 3 0 1 1-6 0 3 3 0 0 1 6 0',arrow:'M4 12h16m-6-6 6 6-6 6',right:'m9 5 7 7-7 7',play:'m8 4 13 8-13 8Z',plus:'M12 4v16M4 12h16',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',camera:'M8 5 10 2h4l2 3h5v16H3V5Zm9 8a5 5 0 1 1-10 0 5 5 0 0 1 10 0',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',fire:'M12 2c0 5-6 5-6 11a6 6 0 1 0 12 0c0-3-1-5-3-7 0 4-2 5-3 6 1-5 1-7 0-10Z',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Zm-4 0a6 6 0 1 1-12 0 6 6 0 0 1 12 0Zm-4 0a2 2 0 1 1-4 0 2 2 0 0 1 4 0',award:'M8 14v8l4-3 4 3v-8M19 8A7 7 0 1 1 5 8a7 7 0 0 1 14 0',bell:'M5 16V9a7 7 0 0 1 14 0v7l2 2H3Zm5 5h4',grid:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z',list:'M8 6h14M8 12h14M8 18h14M2 6h1M2 12h1M2 18h1',file:'M4 2h11l5 5v15H4Zm10 0v6h6M8 12h8m-8 4h6',close:'m6 6 12 12M6 18 18 6',leaf:'M20 3C7 1 1 13 6 18c6 5 16-1 14-15ZM4 21 17 7',check:'m5 12 5 5L21 6',pause:'M8 4v16M16 4v16',refresh:'M20 7V2m0 5h-5M4 17v5m0-5h5M5 7a8 8 0 0 1 14-2M19 17a8 8 0 0 1-14 2',volume:'m11 4-6 5H2v6h3l6 5Zm4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0Zm-4 6v1a7 7 0 0 0 14 0v-1M12 19v3m-4 0h8',calendar:'M4 5h16v16H4ZM8 2v6m8-6v6M4 10h16',search:'m16 16 5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',headphones:'M3 14V11a9 9 0 0 1 18 0v3M3 12h4v9H3Zm14 0h4v9h-4',lock:'M5 10h14v12H5ZM8 10V6a4 4 0 0 1 8 0v4'};
function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.music}"/></svg>`}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const demoSongs=[{id:'sun',title:'晴天',artist:'周杰伦',level:'初级',bpm:72,chords:['C','G','Am','F'],cover:'sunset',progress:38,favorite:true},{id:'wind',title:'风吹麦浪',artist:'李健',level:'初级',bpm:80,chords:['C','Am','F','G'],cover:'forest',progress:0,favorite:false},{id:'night',title:'奇妙能力歌',artist:'陈粒',level:'中级',bpm:68,chords:['Am','F','C','G'],cover:'night',progress:0,favorite:true},{id:'love',title:'爱的罗曼史',artist:'西班牙民谣',level:'初级',bpm:76,chords:['Em','Am','B7','Em'],cover:'paper',progress:0,favorite:false}];
let saved;try{saved=JSON.parse(localStorage.getItem('fret-data'))}catch{}
let state={page:'home',tab:'all',view:'grid',songs:saved?.songs||demoSongs,history:saved?.history||[],goal:saved?.goal||15,search:''};
function persist(){try{localStorage.setItem('fret-data',JSON.stringify({songs:state.songs,history:state.history,goal:state.goal}))}catch{toast('本地存储空间不足，请清理后重试')}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function guitar(){return `<svg class="guitar-art" viewBox="0 0 300 520" fill="none"><defs><linearGradient id="wood" x1="80" y1="200" x2="235" y2="440" gradientUnits="userSpaceOnUse"><stop stop-color="#dcae70"/><stop offset=".5" stop-color="#c89255"/><stop offset="1" stop-color="#bd8047"/></linearGradient><linearGradient id="neck" x1="132" x2="164"><stop stop-color="#674e36"/><stop offset="1" stop-color="#403f30"/></linearGradient><pattern id="grain" width="7" height="10" patternUnits="userSpaceOnUse"><path d="M1 0v10" stroke="#a1703a" stroke-opacity=".15"/></pattern></defs><path d="M146 210c-14-20-55-12-59 15-3 22 13 30 5 49-9 23-39 22-40 69-2 57 38 88 96 88 58 0 98-31 96-88-1-47-31-46-40-69-8-19 8-27 5-49-4-27-45-35-59-15Z" fill="#8c613b" transform="translate(5 6)"/><path d="M146 210c-14-20-55-12-59 15-3 22 13 30 5 49-9 23-39 22-40 69-2 57 38 88 96 88 58 0 98-31 96-88-1-47-31-46-40-69-8-19 8-27 5-49-4-27-45-35-59-15Z" fill="url(#wood)" stroke="#e8c899" stroke-width="3"/><path d="M146 210c-14-20-55-12-59 15-3 22 13 30 5 49-9 23-39 22-40 69-2 57 38 88 96 88 58 0 98-31 96-88-1-47-31-46-40-69-8-19 8-27 5-49-4-27-45-35-59-15Z" fill="url(#grain)"/><circle cx="148" cy="285" r="36" stroke="#97713e" stroke-width="1.5"/><circle cx="148" cy="285" r="32" stroke="#eed2a6" stroke-width="2"/><circle cx="148" cy="285" r="28" fill="#3e3b29"/><circle cx="148" cy="285" r="24" fill="#302f24"/><path d="M176 276c36 8 26 53-8 62l-8-30Z" fill="#685038" opacity=".8"/><path d="m133 48-3 212h36l-3-212Z" fill="url(#neck)" stroke="#a3865e" stroke-width="1.5"/><path d="m132 47-9-43 50-3-10 46Z" fill="#80603c" stroke="#b89763" stroke-width="2"/>${[14,27,40].map(y=>`<rect x="117" y="${y}" width="10" height="5" rx="2" fill="#b9b8a2"/><rect x="170" y="${y-3}" width="10" height="5" rx="2" fill="#b9b8a2"/>`).join('')}${[65,84,103,120,137,153,169,184,198,211,224,236,248].map(y=>`<path d="M132 ${y}h32" stroke="#b0ac8a" stroke-width="1"/>`).join('')}${[94,144,187,222].map(y=>`<circle cx="148" cy="${y}" r="2" fill="#d3d0ae"/>`).join('')}<rect x="114" y="359" width="69" height="16" rx="4" fill="#55412d"/><path d="M128 363h40" stroke="#e2d3ac" stroke-width="3"/>${[137,141.5,146,150.5,155,159.5].map((x,i)=>`<path d="M${x} 15V367" stroke="#ecdebb" stroke-width="${.5+i*.13}" opacity=".85"/>`).join('')}</svg>`}
function landscape(){return '<span class="sun"></span><span class="hill"></span><span class="hill two"></span>'}
function cover(song){if(song.cover==='sunset')return `<div class="album sunset" style="width:100%;height:100%;border-radius:0">${landscape()}</div>`;if(song.cover==='forest')return '<img class="cover-art" src="assets/forest.jpg" alt="晨光中的森林" style="object-fit:cover"><div class="cover-art" style="background:linear-gradient(0deg,#2c483b55,transparent)"></div>';if(song.cover==='night')return '<img class="cover-art" src="assets/night.jpg" alt="紫色舞台灯光" style="object-fit:cover;filter:saturate(.45) brightness(.85)">';return `<svg class="cover-art" viewBox="0 0 300 140"><rect width="300" height="140" fill="#eae6dc"/><g stroke="#a7a498" stroke-width=".7" opacity=".65">${[35,43,51,59,67,94,102,110,118,126].map(y=>`<path d="M25 ${y}h250"/>`).join('')}</g><g fill="#77796c" font-family="Georgia" font-size="32"><text x="45" y="64">𝄞</text><text x="91" y="62">♪</text><text x="131" y="55">♫</text><text x="185" y="62">♩</text><text x="226" y="55">♫</text><text x="49" y="118">♪</text><text x="90" y="122">♫</text><text x="145" y="115">♩</text><text x="185" y="122">♪</text><text x="230" y="115">♫</text></g></svg>`}
function statCards(){let minutes=+(state.history.reduce((n,h)=>n+h.seconds,0)/60).toFixed(1);let acc=state.history.length?Math.round(state.history.reduce((n,h)=>n+h.accuracy,0)/state.history.length):0;return `<div class="stats"><div class="stat"><div class="stat-icon">${icon('clock',21)}</div><div><div class="stat-label">累计练习</div><div class="stat-number">${minutes}<small>分钟</small></div></div></div><div class="stat"><div class="stat-icon">${icon('fire',21)}</div><div><div class="stat-label">连续练习</div><div class="stat-number">${streak()}<small>天</small></div></div></div><div class="stat"><div class="stat-icon">${icon('music',21)}</div><div><div class="stat-label">已练曲目</div><div class="stat-number">${new Set(state.history.map(x=>x.song)).size}<small>首</small></div></div></div><div class="stat"><div class="stat-icon">${icon('target',21)}</div><div><div class="stat-label">平均准确率</div><div class="stat-number">${acc}<small>%</small></div></div></div></div>`}
function streak(){let dates=new Set(state.history.map(h=>new Date(h.date).toDateString())),n=0,d=new Date();if(!dates.has(d.toDateString()))d.setDate(d.getDate()-1);while(dates.has(d.toDateString())){n++;d.setDate(d.getDate()-1)}return n}
const pageNames={home:'练习首页',library:'我的曲谱',learn:'学习路径',stats:'练习记录'};
function render(){let page=state.page;$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><a href="#" class="brand" aria-label="Fret 首页"><span class="brand-mark">${icon('music',21)}</span><span>fret<small>YOUR GUITAR JOURNEY</small></span></a><div class="nav-label">你的练习空间</div>${[['home','home','练习首页'],['library','music','我的曲谱'],['learn','book','学习路径'],['stats','chart','练习记录']].map(([id,ic,t])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}" aria-label="${t}">${icon(ic)}<span>${t}</span>${id==='library'?`<span class="badge">${state.songs.length}</span>`:''}</button>`).join('')}<hr><div class="nav-label">小工具</div><button class="nav-item" data-action="tuner">${icon('tune')}<span>吉他调音器</span></button><button class="nav-item" data-action="metronome">${icon('clock')}<span>节拍器</span></button><div class="practice-tip">${icon('leaf',23)}<h4>每天一点，进步不止。</h4><p>每天 ${state.goal} 分钟，<br>和喜欢的音乐更近一点。</p><button data-action="goal">设置练习目标 ${icon('arrow',13)}</button></div><button class="sidebar-foot" data-action="settings">${icon('settings',16)}<span>偏好设置</span><span>⌘ ,</span></button></aside><main class="main"><header class="topbar"><div class="breadcrumb">我的空间 ${icon('right',12)} <b>${pageNames[page]}</b></div><div class="top-actions"><span class="streak">${icon('fire',16)} ${streak()?`连续练习 ${streak()} 天`:'今天也来拨动琴弦'}</span><button class="icon-btn" data-action="notifications" aria-label="通知">${icon('bell',18)}</button><button class="avatar" data-action="settings" aria-label="个人设置">M</button></div></header><div class="workspace">${page==='home'?home():page==='library'?libraryPage():page==='learn'?learnPage():statsPage()}<footer class="bottom-note">每一次拨弦，都是新的开始。 <span style="padding:0 7px">♪</span> Made for your music.</footer></div></main></div>`;bind();}
function home(){let last=state.songs.find(s=>s.id===state.history.at(-1)?.song)||state.songs[0];return `<div class="page-title"><div><div class="eyebrow">A LITTLE PRACTICE, EVERY DAY</div><h1>今天，也弹点喜欢的。</h1><p>放慢脚步，让音乐成为生活的一部分。</p></div><span class="date-label">${icon('calendar',14)} ${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span></div><section class="hero"><div class="hero-copy"><div class="hero-label">${icon('music',14)} YOUR NEXT FAVORITE SONG STARTS HERE</div><h2>把喜欢的歌，<br>变成指尖的旋律。</h2><p>导入一张乐谱，开启属于你的吉他游戏。</p><div class="hero-actions"><button class="btn primary" data-action="import">${icon('plus',16)} 导入乐谱 ${icon('arrow',15)}</button><small>支持 PDF、图片与屏幕截图</small></div></div><div class="hero-art"><span class="floating-note n1">♪</span>${guitar()}<span class="floating-note n2">♫</span></div></section>${statCards()}<div class="section-heading"><h3>接着上次的旋律 <span>KEEP THE MOMENTUM</span></h3><span style="font-size:10px;color:#a0a797">一步一步，慢慢来</span></div><section class="continue-card"><div class="album sunset">${landscape()}</div><div class="song-info"><h3>${esc(last.title)}</h3><p>${esc(last.artist)} <span style="padding:0 6px">·</span> 和弦弹唱</p><div class="tags"><span class="tag green">${esc(last.level)}</span><span class="tag">${last.bpm} BPM</span><span class="tag">${last.chords.join(' · ')}</span></div></div><div class="continue-progress"><div class="progress-label">练习进度 <b>${state.history.some(h=>h.song===last.id)?last.progress:0}%</b></div><div class="progress-track"><i style="width:${state.history.some(h=>h.song===last.id)?last.progress:0}%"></i></div><div style="font-size:9px;color:#a8ae9d;margin-top:8px">${state.history.some(h=>h.song===last.id)?'继续积累你的练习时光':'从第一个和弦开始'}</div></div><button class="btn primary" data-play="${last.id}">${icon('play',13)} ${state.history.some(h=>h.song===last.id)?'继续练习':'开始练习'}</button></section><div class="section-heading"><h3>我的曲谱 <span>YOUR MUSIC COLLECTION</span></h3><button class="more" data-page="library">查看全部 ${icon('arrow',13)}</button></div>${libraryContent(true)}`}
function libraryPage(){return `<div class="page-title"><div><div class="eyebrow">YOUR MUSIC COLLECTION</div><h1>每一首，都是心头好。</h1><p>收藏喜欢的旋律，用自己的节奏练习。</p></div><button class="btn primary" data-action="import">${icon('plus',15)} 导入乐谱</button></div><input class="search" id="search" placeholder="搜索曲名或艺术家…" value="${esc(state.search)}" aria-label="搜索曲谱" style="margin:0 0 24px">${libraryContent(false)}`}
function libraryContent(home){let songs=state.songs.filter(s=>(state.tab!=='import'||s.imported)&&(state.tab!=='favorite'||s.favorite)&&(!state.search||`${s.title}${s.artist}`.toLowerCase().includes(state.search.toLowerCase())));if(home)songs=songs.filter(s=>s.id!=='sun').slice(0,3);return `<div class="library-tabs">${[['all','全部曲谱'],['import','我的导入'],['favorite','我的收藏']].map(([id,t])=>`<button class="tab ${state.tab===id?'active':''}" data-tab="${id}">${t}</button>`).join('')}<div class="library-tools"><button class="${state.view==='grid'?'active':''}" data-view="grid" aria-label="网格视图">${icon('grid',14)}</button><button class="${state.view==='list'?'active':''}" data-view="list" aria-label="列表视图">${icon('list',16)}</button></div></div><div class="song-grid ${state.view==='list'?'list':''}" id="song-grid">${songs.length?songs.map(songCard).join(''):'<div class="empty-state">还没有曲谱<br><p>导入你的第一首歌，或切换其他分类。</p><button class="btn small" data-action="import">导入乐谱</button></div>'}</div><div class="library-footer"><span>${icon('lock',11)} ${state.songs.filter(x=>x.imported).length} 首导入曲谱 · 安全存储于本机</span><span>${icon('headphones',12)} 准备好吉他，让我们开始吧</span></div>`}
function songCard(s){return `<button class="song-card" data-song="${s.id}"><div class="song-cover cover-${s.cover}">${cover(s)}<span class="corner">${s.imported?'我的导入':'精选曲谱'}</span><span class="cover-note">${icon(s.imported?'file':'music',14)}</span></div><div class="song-details"><div class="song-title">${esc(s.title)}</div><div class="song-author">${esc(s.artist)} <span style="padding:0 5px">·</span> ${s.imported?'自定义和弦':'和弦弹唱'}</div><div class="song-meta"><span class="level"><span class="dots ${s.level==='中级'?'medium':''}"><i></i><i></i><i></i></span>${esc(s.level)}</span><span>${s.bpm} BPM <span style="padding:0 5px">·</span> ${s.chords.length} 个和弦</span></div></div></button>`}
const lessons=[['认识你的吉他','六根琴弦，是音乐故事的起点。','从粗到细，吉他的六根弦依次是 E、A、D、G、B、e。弹奏前，使用左侧调音器逐根调音。坐直，让琴身自然贴近身体。右手轻拨每一根弦，感受不同的音高。'],['和第一个和弦见面','从简单的 Em 开始，找到手感。','Em 和弦：中指按五弦二品，无名指按四弦二品，其余弦保持空弦。指尖尽量垂直，靠近品丝后侧。依次拨响六根弦，确保每根弦都清晰。'],['让节奏流动起来','跟着节拍，弹出你的第一段旋律。','先将速度调为 60 BPM，每次节拍向下拨弦一次。保持右手放松，手腕自然摆动。进入节奏挑战，在和弦经过浅色判定线时按空格键。准确的时机比速度更重要。'],['四个和弦，一首歌','C · G · Am · F，打开新的世界。','先分别练习 C、G、Am 和简易 F。每个和弦保持四拍，再切换下一个。换指时尽量缩小手指的动作。点击下方按钮，用晴天的和弦循环来练习。']];
function learnPage(){return `<div class="page-title"><div><div class="eyebrow">ONE CHORD AT A TIME</div><h1>从第一根琴弦开始。</h1><p>不急着成为高手，先享受每一步。</p></div></div><div class="lesson-grid">${lessons.map((l,i)=>`<button class="lesson" data-lesson="${i}"><div class="num">0${i+1}</div><h3>${l[0]}</h3><p>${l[1]}</p><span class="more">开始学习 ${icon('arrow',14)}</span></button>`).join('')}</div>`}
function statsPage(){let days=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);return {label:d.toLocaleDateString('zh-CN',{weekday:'short'}),mins:state.history.filter(h=>new Date(h.date).toDateString()===d.toDateString()).reduce((n,h)=>n+h.seconds,0)/60}});let max=Math.max(state.goal,...days.map(x=>x.mins));return `<div class="page-title"><div><div class="eyebrow">EVERY NOTE COUNTS</div><h1>听见自己的进步。</h1><p>每一段练习，都是送给未来的礼物。</p></div></div>${statCards()}<div class="section-heading"><h3>本周练习</h3><button class="more" data-action="goal">每日目标 ${state.goal} 分钟 ${icon('right',13)}</button></div><div class="activity">${days.map(d=>`<div><span>${d.mins.toFixed(1)} 分钟</span><i style="height:${Math.max(3,d.mins/max*120)}px;margin-top:8px"></i>${d.label}</div>`).join('')}</div><div class="section-heading" style="margin-top:30px"><h3>最近的旋律</h3></div>${state.history.length?state.history.slice().reverse().slice(0,15).map(h=>`<div class="continue-card" style="margin-bottom:10px"><span class="stat-icon">${icon('music')}</span><div class="song-info"><h3>${esc(state.songs.find(s=>s.id===h.song)?.title||'曲谱')}</h3><p>${new Date(h.date).toLocaleString('zh-CN')}</p></div><span>${h.accuracy}% 准确率</span><span style="color:#9ba590;font-size:11px">${Math.round(h.seconds)} 秒</span></div>`).join(''):'<div class="empty-state">还没有练习记录。完成一轮节奏挑战，你的进步会出现在这里。</div>'}`}
function bind(){document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{state.page=el.dataset.page;state.search='';render();window.scrollTo(0,0)});$('.brand').onclick=e=>{e.preventDefault();state.page='home';render()};document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{state.tab=el.dataset.tab;render()});document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>{state.view=el.dataset.view;render()});document.querySelectorAll('[data-play]').forEach(el=>el.onclick=()=>startGame(el.dataset.play));document.querySelectorAll('[data-song]').forEach(el=>el.onclick=()=>songDetail(el.dataset.song));document.querySelectorAll('[data-lesson]').forEach(el=>el.onclick=()=>lessonDetail(+el.dataset.lesson));if($('#search'))$('#search').oninput=e=>{let p=e.target.selectionStart;state.search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(p,p)}}
let cleanup=null,blobUrls=[];
function closeModal(){if(cleanup){cleanup();cleanup=null}blobUrls.forEach(URL.revokeObjectURL);blobUrls=[];$('#modal-root').innerHTML='';document.body.style.overflow='';}
function modal(title,subtitle,body,wide=false){closeModal();$('#modal-root').innerHTML=`<div class="overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="icon-btn close-modal" aria-label="关闭">${icon('close',20)}</button></div>${body}</section></div>`;document.body.style.overflow='hidden';$('.close-modal').onclick=closeModal;$('.overlay').onclick=e=>{if(e.target.classList.contains('overlay'))closeModal()};$('.close-modal').focus()}
function action(a){if(a==='import')importModal();if(a==='tuner')tunerModal();if(a==='metronome')metronomeModal();if(a==='settings'||a==='goal')settingsModal();if(a==='notifications')modal('练习室的小纸条','一点提醒，一点陪伴。','<div class="help">欢迎来到 Fret。<br>导入你喜欢的曲谱，或从精选曲目开始练习。<br>所有导入文件和练习记录仅保存在当前浏览器中。</div><div class="modal-actions"><button class="btn primary" id="ok">知道了</button></div>'),a==='notifications'&&($('#ok').onclick=closeModal)}
function settingsModal(){modal('给音乐留一点时间','轻松一点，让练习成为习惯。',`<div class="field"><label for="daily-goal">每日练习目标</label><select id="daily-goal">${[5,10,15,20,30,60].map(n=>`<option ${state.goal===n?'selected':''} value="${n}">${n} 分钟</option>`).join('')}</select></div><p class="help">Fret · 浏览器原型 v1.0<br>为 Mac 桌面设计。曲谱文件保存在本机 IndexedDB，练习记录保存在浏览器中。清理网站数据会删除这些内容。</p><div class="modal-actions"><button class="btn primary" id="save-settings">保存设置</button></div>`);$('#save-settings').onclick=()=>{state.goal=+$('#daily-goal').value;persist();closeModal();render();toast('练习目标已更新')}}
function openDB(){return new Promise((resolve,reject)=>{let r=indexedDB.open('fret-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function dbFile(id,file){const db=await openDB();return new Promise((resolve,reject)=>{let tx=db.transaction('files',file?'readwrite':'readonly');let r=file?tx.objectStore('files').put(file,id):tx.objectStore('files').get(id);r.onsuccess=()=>{if(!file)resolve(r.result)};tx.oncomplete=()=>{db.close();if(file)resolve()};tx.onerror=()=>reject(tx.error)})}
function importModal(){modal('把喜欢的旋律，带进来。','导入乐谱，设置和弦，然后开始你的练习。',`<div class="dropzone" tabindex="0" role="button" aria-label="选择乐谱文件">${icon('upload',30)}<h3>将乐谱拖到这里，或点击选择</h3><p>支持 PDF、PNG、JPG、WebP · 最大 20 MB</p></div><input type="file" id="file-input" accept="application/pdf,image/png,image/jpeg,image/webp" hidden><div class="import-options"><button class="btn small" id="screen-capture">${icon('camera',15)} 截取屏幕</button><button class="btn small" id="clipboard-help">⌘ V 粘贴截图</button></div><div id="import-preview"></div><div class="input-row"><div class="field"><label for="song-name">曲谱名称</label><input id="song-name" placeholder="给这首歌起个名字" maxlength="80"></div><div class="field" style="max-width:140px"><label for="song-tempo">速度 BPM</label><input type="number" id="song-tempo" min="40" max="200" value="72"></div></div><div class="field"><label for="song-chords">练习和弦（用空格分隔）</label><input id="song-chords" value="C G Am F" placeholder="例如 C G Am F"></div><p class="help">请对照乐谱手动设置和弦。当前版本保存原始乐谱，并按你设置的和弦顺序生成节奏练习，不会自动识谱。</p><div class="modal-actions"><button class="btn" id="cancel-import">取消</button><button class="btn primary" id="save-import">${icon('plus',15)} 添加到我的曲谱</button></div>`);let file=null;const select=async f=>{if(!f)return;if(!['application/pdf','image/png','image/jpeg','image/webp'].includes(f.type)){toast('请选择 PDF、PNG、JPG 或 WebP 文件');return}if(f.size>20*1024*1024){toast('文件超过 20 MB，请压缩后重试');return}file=f;$('#song-name').value=f.name.replace(/\.[^.]+$/,'');const url=URL.createObjectURL(f);blobUrls.push(url);$('#import-preview').innerHTML=`<div class="file-preview">${f.type==='application/pdf'?`<object data="${url}" type="application/pdf"><p class="help">此浏览器无法嵌入 PDF，文件仍可保存。</p></object>`:`<img src="${url}" alt="导入乐谱预览">`}<div class="file-name">${icon('file',14)} ${esc(f.name)} <span>${(f.size/1024).toFixed(0)} KB</span></div></div>`};const zone=$('.dropzone');zone.onclick=()=>$('#file-input').click();zone.onkeydown=e=>{if(e.key==='Enter')$('#file-input').click()};$('#file-input').onchange=e=>select(e.target.files[0]);zone.ondragover=e=>{e.preventDefault();zone.classList.add('over')};zone.ondragleave=()=>zone.classList.remove('over');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('over');select(e.dataTransfer.files[0])};const paste=e=>{let f=Array.from(e.clipboardData?.files||[])[0];if(f){e.preventDefault();select(new File([f],`截图-${Date.now()}.png`,{type:f.type}))}};document.addEventListener('paste',paste);cleanup=()=>document.removeEventListener('paste',paste);$('#clipboard-help').onclick=()=>toast('先按 ⌃⇧⌘4 截图到剪贴板，再在此处按 ⌘V');$('#screen-capture').onclick=async()=>{if(!navigator.mediaDevices?.getDisplayMedia){toast('请使用 Mac 截图快捷键 ⌃⇧⌘4，再粘贴到这里');return}let stream;try{stream=await navigator.mediaDevices.getDisplayMedia({video:true});let video=document.createElement('video');video.srcObject=stream;await video.play();let canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);canvas.toBlob(b=>{if(b&&$('#import-preview'))select(new File([b],`截图-${Date.now()}.png`,{type:'image/png'}))},'image/png')}catch(e){toast(e.name==='NotAllowedError'?'已取消屏幕截图':'截图不可用，请上传或粘贴图片')}finally{stream?.getTracks().forEach(t=>t.stop())}};$('#cancel-import').onclick=closeModal;$('#save-import').onclick=async()=>{if(!file){toast('请先选择一份乐谱');return}let title=$('#song-name').value.trim(),bpm=+$('#song-tempo').value,chords=$('#song-chords').value.trim().split(/[\s,，·]+/);if(!title){toast('请填写曲谱名称');return}if(bpm<40||bpm>200||!Number.isFinite(bpm)){toast('速度需要在 40–200 BPM 之间');return}if(chords.length>16||chords.some(c=>!chordShapes[c])){toast('支持 C、G、Am、F、Em、Dm、D、A、E、B7，最多 16 个和弦');return}let id='import-'+Date.now();try{await dbFile(id,file);state.songs.push({id,title,artist:'我的曲谱',level:'初级',bpm,chords,cover:'paper',imported:true,fileType:file.type,filename:file.name,progress:0});persist();closeModal();state.page='library';state.tab='import';render();toast('曲谱已保存，可以开始练习了')}catch{toast('文件保存失败，请检查浏览器存储权限')}}}
const chordShapes={C:[-1,3,2,0,1,0],G:[3,2,0,0,0,3],Am:[-1,0,2,2,1,0],F:[-1,-1,3,2,1,1],Em:[0,2,2,0,0,0],Dm:[-1,-1,0,2,3,1],D:[-1,-1,0,2,3,2],A:[-1,0,2,2,2,0],E:[0,2,2,1,0,0],B7:[-1,2,1,2,0,2]};
function chordSvg(c){let shape=chordShapes[c]||chordShapes.C;return `<svg viewBox="0 0 150 155" width="145" height="150" aria-label="${esc(c)} 和弦指法"><g stroke="#c5cfb8">${[0,1,2,3,4,5].map(i=>`<path d="M${30+i*18} 30v100"/>`).join('')}${[0,1,2,3,4].map(i=>`<path d="M30 ${30+i*25}h90" stroke-width="${i===0?4:1}"/>`).join('')}</g>${shape.map((v,i)=>v>0?`<circle cx="${30+i*18}" cy="${30+(v-.5)*25}" r="7" fill="#6c8654"/>`:`<text x="${30+i*18}" y="20" text-anchor="middle" fill="#8c9e78" font-size="12">${v<0?'×':'○'}</text>`).join('')}<g fill="#a0ac94" font-size="9">${['E','A','D','G','B','e'].map((s,i)=>`<text x="${30+i*18}" y="149" text-anchor="middle">${s}</text>`).join('')}</g></svg>`}
function songDetail(id){let s=state.songs.find(x=>x.id===id);modal(esc(s.title),`${esc(s.artist)} · ${s.bpm} BPM · ${esc(s.level)}`,`<div style="display:flex;gap:14px;flex-wrap:wrap;justify-content:center">${s.chords.map(c=>`<div style="text-align:center"><h3 style="font-weight:500">${c}</h3>${chordSvg(c)}</div>`).join('')}</div><p class="help">${s.imported?'练习使用你手动设置的和弦序列。可随时打开原始乐谱对照。':'此曲目为和弦循环练习示例，提供合成和弦音，不含歌曲原版音源与完整原谱。'}<br>每拍一个和弦，跟随判定线按空格键，训练节奏与换弦时机。</p><div class="modal-actions" style="flex-wrap:wrap"><button class="btn" id="favorite">${s.favorite?'取消收藏':'收藏曲谱'}</button>${s.imported?'<button class="btn" id="source">查看原谱</button><button class="btn" id="delete-song">删除</button>':''}<button class="btn primary" id="begin-game">${icon('play',14)} 开始练习</button></div>`);$('#favorite').onclick=()=>{s.favorite=!s.favorite;persist();$('#favorite').textContent=s.favorite?'取消收藏':'收藏曲谱';render()};$('#begin-game').onclick=()=>startGame(id);if(s.imported){$('#source').onclick=async()=>{try{let file=await dbFile(s.id);if(!file){toast('原始文件已被清理，请重新导入');return}let url=URL.createObjectURL(file);modal(esc(s.title),'原始乐谱 · 存储于本机',`${file.type==='application/pdf'?`<object class="source-view" data="${url}" type="application/pdf"><a href="${url}" target="_blank">在新窗口打开 PDF</a></object>`:`<img class="source-view" src="${url}" alt="${esc(s.title)} 原始乐谱">`}<div class="modal-actions"><button class="btn primary" id="source-back">返回曲谱</button></div>`,true);blobUrls.push(url);$('#source-back').onclick=()=>songDetail(id)}catch{toast('无法读取原始文件')}};$('#delete-song').onclick=()=>{modal('删除这份曲谱？','曲谱及其原始文件会从本机移除。','<div class="modal-actions"><button class="btn" id="keep-song">保留</button><button class="btn primary" id="confirm-delete">删除曲谱</button></div>');$('#keep-song').onclick=()=>songDetail(id);$('#confirm-delete').onclick=async()=>{try{let db=await openDB();let tx=db.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.oncomplete=()=>db.close();state.songs=state.songs.filter(s=>s.id!==id);persist();closeModal();render();toast('曲谱已删除')}catch{toast('删除失败，请重试')}}}}}
let audioCtx;
function audio(){if(!audioCtx)audioCtx=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();return audioCtx}
function tone(freq,duration=.2,when=0,volume=.09){let a=audio(),osc=a.createOscillator(),g=a.createGain(),t=a.currentTime+when;osc.type='triangle';osc.frequency.value=freq;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(volume,t+.008);g.gain.exponentialRampToValueAtTime(.001,t+duration);osc.connect(g).connect(a.destination);osc.start(t);osc.stop(t+duration+.02)}
function strum(c){let base=[82.4069,110,146.832,196,246.942,329.628];chordShapes[c].forEach((v,i)=>{if(v>=0)tone(base[i]*2**(v/12),.65,i*.025,.045)})}
function lessonDetail(i){modal(lessons[i][0],`LESSON 0${i+1} · 基础练习`,`<p class="lesson-body">${lessons[i][2]}</p>${i===1?`<div style="text-align:center">${chordSvg('Em')}</div>`:''}<div class="modal-actions">${i<3?'<button class="btn" id="next-lesson">下一课</button>':''}<button class="btn primary" id="try-lesson">${icon('play',14)} 实践一下</button></div>`);if($('#next-lesson'))$('#next-lesson').onclick=()=>lessonDetail(i+1);$('#try-lesson').onclick=()=>i===0?tunerModal():startGame('sun')}
let game=null;
function startGame(id){let s=state.songs.find(x=>x.id===id);if(!s)return;modal(esc(s.title),'节奏挑战 · 和弦经过浅色线时，按下空格键。',`<div class="game-layout"><div class="game-panel"><div class="game-hud"><div>得分<strong id="g-score">0</strong></div><div>连击<strong id="g-combo">0</strong></div><div>进度<strong id="g-progress">0 / 24</strong></div></div><div class="fretboard"><div class="hit-zone"></div><div class="hit-line"></div>${Array.from({length:6},(_,i)=>`<div class="string" style="top:${24+i*35}px"></div><span class="string-label" style="top:${17+i*35}px">${['e','B','G','D','A','E'][i]}</span>`).join('')}<div id="game-notes"></div></div><div class="feedback" id="g-feedback">准备好，就开始吧</div><div class="game-controls"><button class="btn primary" id="g-start">${icon('play',14)} 开始挑战</button><div class="tempo"><button id="tempo-minus" aria-label="减慢">−</button><span id="g-tempo">${s.bpm} BPM</span><button id="tempo-plus" aria-label="加快">+</button></div><button class="icon-btn" id="g-sound" aria-label="切换声音">${icon('volume',18)}</button></div><p class="game-hint">按 <span class="key">space</span> 或点击 <button class="key" id="g-hit">拨弦</button><br>键盘节奏模式 · 真实吉他弹奏请跟随提示自行练习</p></div><aside><div class="chord-card"><small>CURRENT CHORD</small><h3 id="current-chord">${s.chords[0]}</h3><div id="chord-shape">${chordSvg(s.chords[0])}</div><p>指尖靠近品丝<br>让每根琴弦清晰发声</p><small>接下来的和弦</small><div class="next-chords" id="next-chords">${s.chords.slice(1).map(c=>`<span>${c}</span>`).join('')}</div></div></aside></div><div class="progress-track" style="margin-top:20px"><i id="game-bar" style="width:0%"></i></div>`,true);let active=true,raf,startAt=0,elapsed=0,running=false,bpm=s.bpm,score=0,combo=0,hits=0,perfects=0,index=0,sound=true,done=false;const total=24,lead=2500;let marks=Array(total).fill(null),lastTick=-1;function interval(){return 60000/bpm}function time(){return running?elapsed+performance.now()-startAt:elapsed}function showChord(i){let c=s.chords[i%s.chords.length];$('#current-chord').textContent=c;$('#chord-shape').innerHTML=chordSvg(c);$('#next-chords').innerHTML=[1,2,3].map(n=>`<span>${s.chords[(i+n)%s.chords.length]}</span>`).join('')}
function feedback(t){$('#g-feedback').textContent=t}function updateStats(){$('#g-score').textContent=score;$('#g-combo').textContent=combo;$('#g-progress').textContent=`${index} / ${total}`;$('#game-bar').style.width=`${index/total*100}%`}
function finish(){if(done)return;let finalTime=time();done=true;running=false;let seconds=Math.round(Math.max(0,(finalTime-lead)/1000));let accuracy=Math.round(hits/total*100);state.history.push({song:id,date:Date.now(),seconds,accuracy,score});s.progress=Math.max(s.progress||0,accuracy);persist();modal('每一次练习，都算数。','这一轮旋律，为你而响。',`<div class="result">${icon('award',45)}<h3>${accuracy>=80?'节奏感越来越棒了！':'慢慢来，再弹一次就更熟悉。'}</h3><div class="score">${score}</div><p class="help">命中 ${hits} / ${total} · 准确率 ${accuracy}% · 完美节拍 ${perfects}</p><p class="help">这是键盘节奏练习结果，不代表真实吉他的音准。</p></div><div class="modal-actions"><button class="btn" id="finish-game">完成练习</button><button class="btn primary" id="retry-game">${icon('refresh',14)} 再来一轮</button></div>`);$('#retry-game').onclick=()=>startGame(id);$('#finish-game').onclick=()=>{closeModal();render()}}
function loop(){if(!active)return;let t=time(),beat=interval();let html='';for(let i=0;i<total;i++){let delta=lead+i*beat-t;let left=20+delta/lead*75;if(marks[i]===null&&delta< -210){marks[i]='miss';combo=0;index++;showChord(Math.min(i+1,total-1));feedback('MISS · 找回你的节拍');updateStats()}if(left>-10&&left<110)html+=`<div class="game-note ${marks[i]==='hit'?'hit':''}" style="left:calc(${left}% - 23px);opacity:${marks[i]==='miss'?.25:1}">${s.chords[i%s.chords.length]}</div>`}$('#game-notes').innerHTML=html;if(running){let tick=Math.floor((t-lead)/beat);if(tick!==lastTick&&t>=lead&&tick<total){lastTick=tick;if(sound)tone(tick%4===0?1000:750,.07,0,.035)}if(index>=total){finish();return}}raf=requestAnimationFrame(loop)}
function toggle(){if(done)return;if(running){elapsed=time();running=false;$('#g-start').innerHTML=`${icon('play',14)} 继续挑战`;feedback('已暂停')}else{audio();startAt=performance.now();running=true;$('#g-start').innerHTML=`${icon('pause',14)} 暂停`;feedback('跟着节奏，放轻松')}}
function hit(){if(!running||done)return;let t=time(),nearest=-1,min=Infinity;for(let i=0;i<total;i++){if(marks[i]!==null)continue;let delta=Math.abs(lead+i*interval()-t);if(delta<min){nearest=i;min=delta}}if(min<=200){marks[nearest]='hit';hits++;combo++;index++;let perfect=min<=85;score+=perfect?100:60;if(perfect)perfects++;feedback(perfect?'PERFECT · 正是此刻！':'GOOD · 保持节奏');if(sound)strum(s.chords[nearest%s.chords.length]);showChord(Math.min(nearest+1,total-1));updateStats()}else{combo=0;$('#g-combo').textContent=0;feedback('稍等，和弦还在路上')}}
$('#g-start').onclick=toggle;$('#g-hit').onclick=hit;$('#g-sound').onclick=()=>{sound=!sound;$('#g-sound').style.opacity=sound?1:.35;toast(sound?'声音已开启':'声音已关闭')};function changeTempo(n){if(running||elapsed>0){toast('一轮开始后速度固定，重新开始可调整');return}bpm=Math.max(40,Math.min(200,bpm+n));$('#g-tempo').textContent=bpm+' BPM'}$('#tempo-minus').onclick=()=>changeTempo(-4);$('#tempo-plus').onclick=()=>changeTempo(4);const key=e=>{if(e.code==='Space'&&!['INPUT','SELECT'].includes(e.target.tagName)){e.preventDefault();if(!e.repeat)running?hit():toggle()}};document.addEventListener('keydown',key);cleanup=()=>{active=false;cancelAnimationFrame(raf);document.removeEventListener('keydown',key)};$('.close-modal').focus();loop();}
function metronomeModal(){modal('找到你的节拍','放松右手，让每次拨弦都有节奏。',`<div class="tuner"><div class="tuner-note" id="metro-beat">♩</div><div class="field"><label for="metro-speed">速度 <span id="metro-label">72</span> BPM</label><input type="range" id="metro-speed" min="40" max="200" value="72"></div><div class="string-buttons" id="metro-dots">${[1,2,3,4].map(i=>`<button tabindex="-1">${i}</button>`).join('')}</div><button class="btn primary" id="metro-toggle">${icon('play',14)} 开始</button></div>`);let timer,bpm=72,beat=0,on=false;const tick=()=>{tone(beat===0?1000:700,.08);$('#metro-dots').children[beat].classList.add('active');Array.from($('#metro-dots').children).forEach((el,i)=>el.classList.toggle('active',i===beat));$('#metro-beat').style.transform=`rotate(${beat%2?12:-12}deg)`;beat=(beat+1)%4;timer=setTimeout(tick,60000/bpm)};$('#metro-speed').oninput=e=>{bpm=+e.target.value;$('#metro-label').textContent=bpm};$('#metro-toggle').onclick=()=>{on=!on;if(on){audio();tick()}else clearTimeout(timer);$('#metro-toggle').innerHTML=`${icon(on?'pause':'play',14)} ${on?'暂停':'开始'}`};cleanup=()=>clearTimeout(timer)}
function tunerModal(){modal('先调好音，再开始。','标准调弦 · E A D G B e',`<div class="tuner"><div class="tuner-note" id="tuner-note">E</div><div class="help" id="tuner-freq">82.41 Hz · 点击琴弦试听标准音</div><div class="tuner-bar"><i id="tuner-pointer"></i></div><div class="help" id="tuner-status">开启麦克风，检测单根琴弦音高</div><div class="string-buttons">${['E','A','D','G','B','e'].map((s,i)=>`<button data-string="${i}" class="${i===0?'active':''}">${s}</button>`).join('')}</div><button class="btn primary" id="listen-mic">${icon('mic',16)} 开启麦克风调音</button><p class="help">麦克风声音仅在本机分析，不上传。<br>请在安静环境中单独拨响一根弦。</p></div>`);const freqs=[82.4069,110,146.832,196,246.942,329.628];let stream,ctx,analyser,raf,active=true,selected=0;document.querySelectorAll('[data-string]').forEach(b=>b.onclick=()=>{selected=+b.dataset.string;document.querySelectorAll('[data-string]').forEach(el=>el.classList.toggle('active',el===b));$('#tuner-note').textContent=['E','A','D','G','B','e'][selected];$('#tuner-freq').textContent=freqs[selected].toFixed(2)+' Hz · 标准音';tone(freqs[selected],1.6,0,.15)});$('#listen-mic').onclick=async()=>{if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;cancelAnimationFrame(raf);$('#listen-mic').innerHTML=`${icon('mic',16)} 开启麦克风调音`;$('#tuner-status').textContent='已停止麦克风';return}try{stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});if(!active){stream.getTracks().forEach(t=>t.stop());return}ctx=audio();analyser=ctx.createAnalyser();analyser.fftSize=4096;ctx.createMediaStreamSource(stream).connect(analyser);$('#listen-mic').textContent='停止麦克风';let data=new Float32Array(analyser.fftSize),last=0;function update(t){if(!active||!stream)return;if(t-last>110){last=t;analyser.getFloatTimeDomainData(data);let pitch=detectPitch(data,ctx.sampleRate);if(pitch){let cents=1200*Math.log2(pitch/freqs[selected]);$('#tuner-freq').textContent=pitch.toFixed(1)+' Hz';$('#tuner-pointer').style.left=Math.max(1,Math.min(99,50+cents/2))+'%';$('#tuner-status').textContent=Math.abs(cents)<7?'音准很棒 ✓':cents<0?'偏低 · 稍微拧紧琴弦':'偏高 · 稍微放松琴弦'}else $('#tuner-status').textContent='正在聆听，请单独拨响选中的琴弦…'}raf=requestAnimationFrame(update)}raf=requestAnimationFrame(update)}catch(e){$('#tuner-status').textContent=e.name==='NotAllowedError'?'未获得麦克风权限，可点击琴弦试听调音。':'麦克风不可用，可点击琴弦试听标准音。'}};cleanup=()=>{active=false;stream?.getTracks().forEach(t=>t.stop());cancelAnimationFrame(raf)}}
function detectPitch(buf,rate){let rms=Math.sqrt(buf.reduce((n,v)=>n+v*v,0)/buf.length);if(rms<.008)return null;let n=2048,min=Math.floor(rate/400),max=Math.floor(rate/65),best=0,bestLag=0,prev=1,found=false;for(let lag=min;lag<max;lag++){let corr=0,a=0,b=0;for(let i=0;i<n;i++){corr+=buf[i]*buf[i+lag];a+=buf[i]*buf[i];b+=buf[i+lag]*buf[i+lag]}corr/=Math.sqrt(a*b)||1;if(corr>best&&corr>prev){best=corr;bestLag=lag}if(best>.9&&corr<prev){found=true;break}prev=corr}return best>.75&&bestLag?rate/bestLag:null}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.metaKey||e.ctrlKey)&&e.key===','){e.preventDefault();settingsModal()}if((e.metaKey||e.ctrlKey)&&e.key==='o'){e.preventDefault();importModal()}if(e.key==='Tab'&&$('.modal')){let els=Array.from($('.modal').querySelectorAll('button,input,select,[tabindex="0"],a')).filter(el=>!el.hidden&&el.offsetParent!==null);if(!els.length)return;let first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});render();
